// Package stdlib provides HTTP library support for FV 2.0
package stdlib

import (
	"fmt"
)

// HttpMethod represents HTTP methods
type HttpMethod string

const (
	MethodGET    HttpMethod = "GET"
	MethodPOST   HttpMethod = "POST"
	MethodPUT    HttpMethod = "PUT"
	MethodDELETE HttpMethod = "DELETE"
	MethodPATCH  HttpMethod = "PATCH"
	MethodOPTIONS HttpMethod = "OPTIONS"
)

// HttpRequest represents an HTTP request
type HttpRequest struct {
	Method  string
	Path    string
	Headers map[string]string
	Body    string
	Query   map[string]string
}

// HttpResponse represents an HTTP response
type HttpResponse struct {
	StatusCode int
	StatusText string
	Headers    map[string]string
	Body       string
}

// HttpServer represents an HTTP server
type HttpServer struct {
	Port     int
	Host     string
	Routes   map[string]Handler
	Handlers map[string]Handler
}

// Handler is a function that handles HTTP requests
type Handler func(*HttpRequest) *HttpResponse

// NewHttpServer creates a new HTTP server
func NewHttpServer(port int) *HttpServer {
	return &HttpServer{
		Port:     port,
		Host:     "localhost",
		Routes:   make(map[string]Handler),
		Handlers: make(map[string]Handler),
	}
}

// GET registers a GET route
func (s *HttpServer) GET(path string, handler Handler) {
	routeKey := fmt.Sprintf("GET %s", path)
	s.Routes[routeKey] = handler
}

// POST registers a POST route
func (s *HttpServer) POST(path string, handler Handler) {
	routeKey := fmt.Sprintf("POST %s", path)
	s.Routes[routeKey] = handler
}

// PUT registers a PUT route
func (s *HttpServer) PUT(path string, handler Handler) {
	routeKey := fmt.Sprintf("PUT %s", path)
	s.Routes[routeKey] = handler
}

// DELETE registers a DELETE route
func (s *HttpServer) DELETE(path string, handler Handler) {
	routeKey := fmt.Sprintf("DELETE %s", path)
	s.Routes[routeKey] = handler
}

// HandleFunc registers a handler with a custom key
func (s *HttpServer) HandleFunc(key string, handler Handler) {
	s.Handlers[key] = handler
}

// ListenAndServe starts the HTTP server
func (s *HttpServer) ListenAndServe() error {
	fmt.Printf("Server listening on %s:%d\n", s.Host, s.Port)
	return nil
}

// RouteRequest routes an HTTP request to the appropriate handler
func (s *HttpServer) RouteRequest(req *HttpRequest) *HttpResponse {
	routeKey := fmt.Sprintf("%s %s", req.Method, req.Path)

	// Try to find registered route
	if handler, ok := s.Routes[routeKey]; ok {
		return handler(req)
	}

package main

import (
	"flag"
	"fmt"
	"io/ioutil"
	"os"
	"strings"

	"fv2-lang/internal/codegen"
	"fv2-lang/internal/lexer"
	"fv2-lang/internal/parser"
	"fv2-lang/internal/typechecker"
)

func main() {
	flag.Usage = func() {
		fmt.Fprintf(os.Stderr, "Usage: fv2 [options] <file.fv>\n")
		flag.PrintDefaults()
	}

	tokenize := flag.Bool("tokenize", false, "Show tokens only")
	help := flag.Bool("help", false, "Show help")

	flag.Parse()

	if os.Getenv("DEBUG") == "1" {
		fmt.Fprintf(os.Stderr, "os.Args: %v\n", os.Args)
		fmt.Fprintf(os.Stderr, "flag.Args(): %v\n", flag.Args())
	}

	if *help {
		flag.Usage()
		os.Exit(0)
	}

	args := flag.Args()

	if os.Getenv("DEBUG") == "1" {
		fmt.Fprintf(os.Stderr, "args[0]: %q, os.Args[0]: %q, match: %v\n", args[0], os.Args[0], args[0] == os.Args[0])
	}

	// Skip first arg if it's the program itself (Termux quirk)
	startIdx := 0
	if len(args) > 0 && (args[0] == os.Args[0] || strings.HasSuffix(args[0], "/bin/fv2")) {
		startIdx = 1
	}

	if len(args)-startIdx <= 0 {
		fmt.Fprintf(os.Stderr, "Error: No input file specified\n")
		flag.Usage()
		os.Exit(1)
	}

	filename := args[startIdx]

	if os.Getenv("DEBUG") == "1" {
		fmt.Fprintf(os.Stderr, "Opening file: %q (%d bytes in arg)\n", filename, len(filename))
	}

	// Read source file
	source, err := ioutil.ReadFile(filename)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading file '%s': %v\n", filename, err)
		os.Exit(1)
	}

	// Compile
	sourceStr := string(source)

	// Debug: Check for null bytes
	if os.Getenv("DEBUG") == "1" {
		fmt.Fprintf(os.Stderr, "File size: %d bytes\n", len(source))
		for i, b := range source {
			if b == 0 {
				fmt.Fprintf(os.Stderr, "Warning: NULL byte at position %d\n", i)
			}
		}
	}
	if err := compile(sourceStr, *tokenize); err != nil {
		fmt.Fprintf(os.Stderr, "Compilation error: %v\n", err)
		os.Exit(1)
	}
}

func compile(source string, tokensOnly bool) error {
	// Step 1: Lexing
	lex, err := lexer.New(source)
	if err != nil {
		return fmt.Errorf("lexer initialization failed: %w", err)
	}

	tokens, err := lex.Tokenize()
	if err != nil {
		return fmt.Errorf("tokenization failed: %w", err)
	}

	if tokensOnly {
		fmt.Printf("=== Tokens ===\n")
		for _, token := range tokens {
			fmt.Printf("%v\n", token)
		}
		return nil
	}

	// Step 2: Parser
	p := parser.New(tokens)
	program, err := p.Parse()
	if err != nil {
		return fmt.Errorf("parsing failed: %w", err)
	}

	// Step 3: Type Checker
	checker := typechecker.New()
	typeErrors, _ := checker.Check(program)
	hasTypeErrors := len(typeErrors) > 0

	fmt.Printf("// FV 2.0 Compiler\n")
	fmt.Printf("// Tokenized %d tokens\n", len(tokens))
	fmt.Printf("// Parsed: %d definitions, %d statements in main\n", len(program.Definitions), len(program.MainBody))

	if hasTypeErrors {
		fmt.Printf("// Type checking: %d error(s)\n", len(typeErrors))
		for _, e := range typeErrors {
			fmt.Printf("// %s\n", e.String())
		}
		return fmt.Errorf("type checking failed")
	}
	fmt.Printf("// Type checking: OK\n")

	// Step 4: Code Generator
	gen := codegen.New()
	cCode, err := gen.Generate(program)
	if err != nil {
		return fmt.Errorf("code generation failed: %w", err)
	}

	fmt.Printf("// C code generation: OK\n")
	fmt.Printf("\n// Generated C code:\n")
	fmt.Printf("%s\n", cCode)

	return nil
}

