				// Identifier pattern: variable binding (simplified as true)
				condition = "1" // In full impl, would bind variable
			case *ast.WildcardPattern:
				// Wildcard pattern: always matches (default case)
				condition = "1"
			default:
				// Unknown pattern type
				condition = "1"
			}
		}

		if i == 0 {
			g.writeLine(fmt.Sprintf("if (%s) {", condition))
		} else {
			g.writeLine(fmt.Sprintf("} else if (%s) {", condition))
		}
		g.indent++

		for _, stmt := range arm.Body {
